  for dp,_,fs in os.walk(root):
    for fn in fs:
      p=os.path.join(dp,fn); data=b''
      try:
        if zipfile.is_zipfile(p):
          z=zipfile.ZipFile(p); data=b' '.join(z.read(n) for n in z.namelist() if n.endswith(('.xml','.rels')))
        else:
          data=open(p,'rb').read()
      except Exception:
        continue
